for(const entry of CURRENT_DEVICE_ADDITIONS){
  let group=TECH_CATALOG[entry.category].find(g=>g.brand===entry.brand);
  if(!group){group={brand:entry.brand,sourceUrl:entry.brandSourceUrl||entry.sourceUrl,models:[]};TECH_CATALOG[entry.category].push(group);}
  const {category,brand,brandSourceUrl,...model}=entry;
  const index=group.models.findIndex(m=>m.id===entry.id);
  if(index>=0)group.models[index]={...group.models[index],...model};else group.models.push(model);
}
for(const brands of Object.values(TECH_CATALOG))for(const group of brands)group.models.sort((a,b)=>(b.releaseYear||0)-(a.releaseYear||0)||Number(b.availability==='coming-soon')-Number(a.availability==='coming-soon'));

