/* Illustrative, deterministic suggestions for the interactive concept. */
function suggestTechHelp(input) {
  if (typeof input !== 'string' || !input.trim()) return [];
  const q = input.toLowerCase().trim()
    .replace(/[’‘]/g, "'")
    .replace(/\bnetflx\b/g, 'netflix')
    .replace(/\bsamung\b/g, 'samsung')
    .replace(/\bprnter\b/g, 'printer')
    .replace(/\bwi[ -]?fi\b/g, 'wifi')
    .replace(/\blog[ -]?in\b/g, 'login')
    .replace(/\bsign[ -]?in\b/g, 'signin')
    .replace(/\bsign[ -]?up\b/g, 'signup');
  const has = (r) => r.test(q);
  const brandNames = {
    samsung: 'Samsung', hp: 'HP', dell: 'Dell', lenovo: 'Lenovo',
    asus: 'ASUS', acer: 'Acer', apple: 'Apple', sony: 'Sony', lg: 'LG',
    canon: 'Canon', epson: 'Epson', brother: 'Brother', microsoft: 'Microsoft',
    google: 'Google', amazon: 'Amazon', roku: 'Roku', hisense: 'Hisense',
    toshiba: 'Toshiba', panasonic: 'Panasonic'
  };
  let brand = Object.entries(brandNames).find(([word]) =>
    new RegExp('\\b' + word + '\\b').test(q))?.[1] || null;
  if (!brand && has(/\b(?:iphone|ipad|macbook|imac|mac)\b/)) brand = 'Apple';
  if (!brand && has(/\b(?:galaxy)\b/)) brand = 'Samsung';
  if (!brand && has(/\b(?:pixel|chromecast)\b/)) brand = 'Google';

  const appMatchers = [
    ['Google Drive', /\bgoogle drive\b/], ['Google Photos', /\bgoogle photos\b/], ['Google Meet', /\bgoogle meet\b/], ['Microsoft Edge', /\b(?:microsoft )?edge\b/],
    ['Netflix', /\bnetflix\b/], ['YouTube', /\byoutube\b/],
    ['Disney+', /\bdisney(?:\s*plus|\+)?\b/],
    ['Prime Video', /\b(?:prime video|amazon prime)\b/],
    ['Spotify', /\bspotify\b/], ['WhatsApp', /\bwhats ?app\b/],
    ['Zoom', /\bzoom\b/], ['Teams', /\b(?:microsoft )?teams\b/],
    ['Gmail', /\bgmail\b/], ['Outlook', /\boutlook\b/],
    ['Apple account', /\bapple\s+(?:id|account|password)\b/],
    ['Google account', /\bgoogle\s+(?:account|password)\b/],
    ['Microsoft account', /\bmicrosoft\s+(?:account|password)\b/]
  ];
  const app = appMatchers.find(([, pattern]) => has(pattern))?.[0] || null;
  const accountWording = has(/\b(?:account|password|passcode|signin|signup|login|log\s*in|verification code|forgot(?:ten)?|reset password)\b/);
  let issue = null;
  if (has(/\b(?:signup|register|registration|create (?:an? )?account|new account)\b/)) issue = 'signup';
  else if (accountWording) issue = 'signin';
  else if (has(/\b(?:install|download|uninstall|set up|setup)\b/)) issue = 'install';
  else if (has(/\b(?:sound|audio|volume|mute|hear)\b/)) issue = 'sound';
  else if (has(/\b(?:power|battery|charg(?:e|es|ed|ing)|turn on|switch on|start up|boot)\b/) && !has(/\b(?:black|blank) (?:screen|display)\b/)) issue = 'power';
  else if (has(/\b(?:screen|display|picture|flicker(?:ing)?|black|blank)\b/)) issue = 'screen';
  else if (has(/\b(?:slow|sluggish|lag(?:ging)?|freez(?:e|es|ing)|frozen)\b/)) issue = 'slow';
  else if (has(/\b(?:connect(?:ion|ing|ed)?|disconnect(?:ed|ing)?|wifi|wireless|bluetooth|offline|pair(?:ing)?|network|router|internet|can(?:not|'t) find|not (?:find|detect)(?:ing|ed)?)\b/)) issue = 'connection';
  else if (has(/\b(?:play(?:ing|back)?|stream(?:ing)?|buffer(?:ing)?|watch(?:ing)?|won't open|cannot open|can't open|not (?:open|load)(?:ing)?|won't load)\b/)) issue = 'playback';

  const devices = [];
  if (has(/\b(?:tv|television|smart tv|telly|roku|fire ?stick|fire tv|chromecast)\b/)) devices.push(['tv', 'TV']);
  if (has(/\b(?:phone|mobile|smartphone|iphone|ipad|tablet|android|galaxy|pixel)\b/)) devices.push(['mobile', has(/\biphone\b/) ? 'iPhone' : has(/\bipad\b/) ? 'iPad' : has(/\btablet\b/) ? 'Tablet' : 'Phone']);
  if (has(/\b(?:laptop|notebook|macbook|chromebook)\b/)) devices.push(['laptop', has(/\bmacbook\b/) ? 'MacBook' : has(/\bchromebook\b/) ? 'Chromebook' : 'Laptop']);
  if (has(/\b(?:desktop|tower|imac)\b/)) devices.push(['desktop', has(/\bimac\b/) ? 'iMac' : 'Desktop computer']);
  if (has(/\b(?:printer|printing|print|scanner|scan|deskjet|officejet|laserjet|pixma)\b/)) devices.push(['printer', has(/\bscanner\b/) && !has(/\bprinter\b/) ? 'Scanner' : 'Printer']);

  const genericComputer = has(/\b(?:computer|pc|windows|mac)\b/) && !devices.some(([c]) => c === 'laptop' || c === 'desktop');
  const source = devices.filter(([c]) => c !== 'printer').map(([, label]) => label).join(' and ') || (genericComputer ? 'Computer' : null);
  const deviceName = (label, name = brand) => /^(?:iPhone|iPad|MacBook|Chromebook|iMac)$/.test(label) ? label : (name ? name + ' ' : '') + label;
  const other = [
    ['Game console', /\b(?:xbox|playstation|ps5|ps4|nintendo|console)\b/],
    ['Headphones or speaker', /\b(?:headphones?|earbuds?|airpods?|speaker|soundbar|echo|alexa)\b/],
    ['Smartwatch', /\b(?:smartwatch|apple watch|samsung watch|galaxy watch|fitbit|garmin)\b|^(?:my )?watch(?: is| won| can| not|$)/],
    ['Camera', /\bcamera\b/]
  ].find(([, pattern]) => has(pattern));
  const labels = {
    sound: 'Sound problem', power: 'Power or charging problem', screen: 'Screen or picture problem',
    connection: 'Connection problem', slow: 'Running slowly', signup: 'Create an account',
    signin: 'Account or sign-in help', playback: 'Opening or playing content', install: 'Setup or installation'
  };
  const candidate = (category, deviceLabel, extras = {}) => {
    const finalBrand = extras.brand === undefined ? brand : extras.brand;
    const finalApp = extras.app === undefined ? app : extras.app;
    const title = finalApp && category !== 'apps' ? finalApp + ' on ' + deviceLabel : finalApp || deviceLabel;
    return {
      label: extras.label || (title + (issue ? ' · ' + labels[issue] : ' · Get help')),
      category, brand: finalBrand, app: finalApp, issue,
      sourceDevice: extras.sourceDevice === undefined ? null : extras.sourceDevice,
      deviceLabel, ...extras
    };
  };

  // Account language takes precedence over an incidental hardware reference.
  if (accountWording) {
    const accountName = app || (brand ? brand + ' account' : 'App or account');
    return [candidate('apps', accountName, { app: app || accountName, sourceDevice: source })];
  }

  // A printer is the target when a phone/computer is trying to find or use it.
  const printer = devices.find(([c]) => c === 'printer');
  if (printer) {
    const printerBrand = Object.entries(brandNames).find(([word]) =>
      new RegExp('\\b' + word + '(?:\\s+[a-z0-9-]+){0,2}\\s+(?:printer|scanner)\\b').test(q))?.[1];
    // A source computer's brand must not become the printer's brand.
    const targetBrand = printerBrand || (/^(HP|Canon|Epson|Brother)$/.test(brand || '') ? brand : null);
    return [candidate('printer', (targetBrand ? targetBrand + ' ' : '') + printer[1], {
      brand: targetBrand,
      sourceDevice: source,
      label: (targetBrand ? targetBrand + ' ' : '') + printer[1] + (source ? ' with your ' + source.toLowerCase() : '') + (issue ? ' · ' + labels[issue] : '')
    })];
  }

  // An explicit peripheral wins over generic brand-only device suggestions.
  if (other) return [candidate('other', deviceName(other[0]), { sourceDevice: source })];
  if (devices.length) return devices.slice(0, 3).map(([category, label]) => {
    const name = deviceName(label);
    const pairedSource = devices.filter(([c]) => c !== category).map(([, otherLabel]) => otherLabel).join(' and ') || (genericComputer ? 'Computer' : null);
    return candidate(category, name, { sourceDevice: pairedSource, label: (app ? app + ' on ' : '') + name + (issue ? ' · ' + labels[issue] : '') });
  });
  if (genericComputer) return [candidate('laptop', 'Laptop'), candidate('desktop', 'Desktop computer')];
  if (app) return [candidate('apps', app)];
  if (has(/\b(?:wifi|internet|router|modem|broadband|wireless|network)\b/)) return [candidate('wifi', 'Wi-Fi & internet')];

  const prefixBrand = !brand && /^[a-z]{2,}$/.test(q) ? Object.keys(brandNames).filter((key) => key.startsWith(q)) : [];
  const brands = brand ? [brand] : prefixBrand.map((key) => brandNames[key]);
  if (brands.length) {
    return brands.flatMap((name) => {
      const choices = /^(Canon|Epson|Brother)$/.test(name) ? [['printer', 'Printer or scanner']] :
        name === 'HP' ? [['printer', 'Printer'], ['laptop', 'Laptop'], ['desktop', 'Desktop computer']] :
        /^(Dell|Lenovo|ASUS|Acer|Microsoft)$/.test(name) ? [['laptop', 'Laptop'], ['desktop', 'Desktop computer']] :
        name === 'Samsung' ? [['mobile', 'Phone or tablet'], ['tv', 'TV'], ['other', 'Other device']] :
        name === 'Apple' ? [['mobile', 'iPhone or iPad'], ['laptop', 'MacBook'], ['desktop', 'Desktop Mac']] :
        /^(LG|Sony|Hisense|Toshiba|Panasonic|Roku)$/.test(name) ? [['tv', 'TV'], ['other', 'Other device']] :
        [['mobile', 'Phone or tablet'], ['other', 'Other device']];
      return choices.map(([category, label]) => candidate(category, name + ' ' + label, {brand: name}));
    }).slice(0, 3);
  }
  if (has(/\b(?:app|apps|application|software|program|programme)\b/)) return [candidate('apps', 'App or software')];
  return [];
}

