ADVANCED_GUIDES.push(...[{"id":"sony-xm6-playback-control","title":"Find why your WH-1000XM6 music cuts out or switches","categories":["other"],"brands":["Sony"],"modelIds":["sony-wh1000xm6"],"softwareMatch":["Sound Connect"],"symptoms":["sound","connection","playback","bluetooth"],"connectionKinds":["bluetooth"],"scope":"Sony WH-1000XM6, Bluetooth music, with Sony | Sound Connect on a connected smartphone. These checks cover playback settings; they do not cover wired audio, calls or a headset that will not power on.","sourceTitle":"Sony: WH-1000XM6 troubleshooting and Help Guide","sourceUrl":"https://helpguide.sony.net/mdr/2984/v1/en/contents/TP1001856788.html","reviewedAt":"2026-09-19","steps":[{"title":"Start with the connected headset","body":"Open Sony | Sound Connect on the phone connected to your headphones. Check that WH-1000XM6 appears, then start a familiar track at a comfortable volume.","check":"If the app cannot connect, stop here and use its connection instructions before changing playback settings.","successLabel":"My WH-1000XM6 is connected","failureLabel":"It is missing or disconnected"},{"title":"Test a steadier connection","body":"Find the sound quality mode in Sound Connect. Note the current choice, then select Prioritize Stable Connection and replay the track.","check":"This favours connection stability. Improvement points to the previous mode or listening conditions; it does not prove the headphones are faulty.","successLabel":"I tested this mode","failureLabel":"I cannot find this setting"},{"title":"Check whether speech lowers the music","body":"If music becomes quiet when you speak or hum, check Speak-to-Chat in Sound Connect. If enabled, turn it off temporarily and test again. Otherwise leave it unchanged.","check":"If the unwanted lowering stops, Speak-to-Chat explains it. You can restore this optional feature later.","successLabel":"I checked Speak-to-Chat","failureLabel":"The control is unavailable"},{"title":"Choose the device that should play","body":"If two devices are connected, stop audio on the other one, then start the track from the device you want to hear. If only one is connected, replay the track there.","check":"With two connected devices, starting playback on the other device can switch the music source. This test helps identify that change.","successLabel":"I tested the intended device","failureLabel":"I cannot identify the other device"},{"title":"Retest after a normal restart","body":"Turn the headset off, charge it if needed, then turn it on. Save your work and restart the playback phone or computer. Reconnect and test the same track.","check":"This is a normal restart. Do not choose factory initialization as part of these checks.","successLabel":"I tested the track again","failureLabel":"I cannot complete this check"}],"closing":"If playback is still unreliable, open Help in Sound Connect or Sony’s linked troubleshooting page. Tell support which settings changed the result. A fix is only confirmed when the original problem stops."},{"id":"canon-g3290-network-report","title":"Read your PIXMA G3290 Wi-Fi diagnosis","categories":["printer"],"brands":["Canon"],"modelIds":["canon-pixma-g3290"],"softwareMatch":["Windows","macOS","Mobile print app","Printer app","Canon PRINT"],"symptoms":["connection","printing","wifi","offline"],"connectionKinds":["wifi"],"scope":"Canon PIXMA G3290 on Wi-Fi through a home router, using its touchscreen network report. Supports checks from a computer, phone or tablet. Not for USB or Wireless Direct connections. The official G3090 series manual explicitly includes G3290.","sourceTitle":"Canon: G3090 series network diagnostics, including G3290","sourceUrl":"https://ij.manual.canon/ij/webmanual/Manual/All/G3090%20series/EN/NTR/ntr_trouble0300.html","reviewedAt":"2026-09-19","steps":[{"title":"Check the home Wi-Fi first","body":"Confirm the printer and router are on. On the phone or computer you print from, join your home Wi-Fi and open a website. Check that Wi-Fi is enabled on the printer.","check":"If that device cannot get online, or the printer’s Wi-Fi is disabled, address that connection before interpreting the report.","successLabel":"Home Wi-Fi works and printer Wi-Fi is on","failureLabel":"One of these checks failed"},{"title":"Print the network details","body":"Load at least three sheets of A4 or Letter plain paper. On the printer select Setup → Printer settings → LAN settings → Print details → Yes. When asked whether to print passwords, choose OFF.","check":"Keep the report private: it includes network and device details even with password printing off.","successLabel":"The report printed","failureLabel":"It did not print or menus differ"},{"title":"Find the diagnostic code","body":"Look at item 2-2, Result Codes. Continue here only if C-0 appears by itself. C-1 indicates disabled Wi-Fi, C-3 means no IP address was assigned, and C-5 means the chosen network could not be reached.","check":"If any other code appears, use its entry on the linked Canon page. Do not guess new router or IP settings.","successLabel":"C-0 is the only code","failureLabel":"Another code appears / I cannot find it"},{"title":"Compare the network names","body":"Find item 3-2-6 on the report. Compare that network name with the home Wi-Fi used by the phone or computer sending the print job.","check":"Matching names support the same-network setup. A mismatch needs the correct Wi-Fi setup before you retry printing.","successLabel":"The network names match","failureLabel":"They differ or I am unsure"},{"title":"Try one fresh print job","body":"Return to the app you print from, choose this Canon printer and send a short document. Note whether the printer appears and whether the page starts printing.","check":"C-0 confirms the printer’s connection check, not every app or computer setting. If printing still fails, keep the report for Canon support.","successLabel":"I tried a new print job","failureLabel":"The printer is still unavailable"}],"closing":"If printing is still blocked, use the linked Canon diagnostics with the result code and your phone or computer type. These checks do not require a network reset or disabling security software."}]);
for(const entry of CATALOG_RELEASE_UPDATE){
  let brand=TECH_CATALOG[entry.category].find(b=>b.brand===entry.brand);
  if(!brand){brand={brand:entry.brand,sourceUrl:entry.brandSourceUrl,models:[]};TECH_CATALOG[entry.category].push(brand);}
  brand.models.push(entry.model);
}
for(const brands of Object.values(TECH_CATALOG))for(const brand of brands){
  for(const model of brand.models)if(PAID_MODEL_GUIDES[model.id])model.paidGuideIds=PAID_MODEL_GUIDES[model.id];
  brand.models.sort((a,b)=>(Number(b.releaseYear)||0)-(Number(a.releaseYear)||0)||Number(!!b.catalogFeatured)-Number(!!a.catalogFeatured));
}
