    if(current==='about_app')return {section:'About Loop',q:'Small checks. Clear next steps.',detail:'Loop helps you work through everyday technology problems, with a source link and coverage notes for every guide.',scope:'Catalogue reviewed '+TECH_CATALOG_META.reviewedAt+'. Availability can differ by region. The catalogue is curated and updated with app releases; it is not a live product feed. Device illustrations represent product families.',list:true,choices:[['How Loop works','welcome'],['Privacy','privacy'],['Terms of use','terms'],['Back','@back']]};
